svg.script:
(() => {
  const root = document.documentElement;
  const q = (n, a, b) => Math.min(b, Math.max(a, n));

  function parseColor(value) {
    const v = String(value || '').trim().toLowerCase();
    let m = v.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
    if (m) {
      let h = m[1];
      if (h.length === 3) h = h.replace(/(.)/g, '$1$1');
      return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) / 255);
    }
    m = v.match(/^rgb\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)\s*\)$/);
    if (m) return [q(+m[1] / 255, 0, 1), q(+m[2] / 255, 0, 1), q(+m[3] / 255, 0, 1)];
    return null;
  }

  const linear = c => c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  const gamma = c => c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055;

  function rgbToOklch(rgb) {
    const r = linear(rgb[0]), g = linear(rgb[1]), b = linear(rgb[2]);
    const l = Math.cbrt(0.4122214708*r + 0.5363325363*g + 0.0514459929*b);
    const m = Math.cbrt(0.2119034982*r + 0.6806995451*g + 0.1073969566*b);
    const s = Math.cbrt(0.0883024619*r + 0.2817188376*g + 0.6299787005*b);
    const L = 0.2104542553*l + 0.7936177850*m - 0.0040720468*s;
    const a = 1.9779984951*l - 2.4285922050*m + 0.4505937099*s;
    const bb = 0.0259040371*l + 0.7827717662*m - 0.8086757660*s;
    const C = Math.hypot(a, bb);
    const h = (Math.atan2(bb, a) * 180 / Math.PI + 360) % 360;
    return { L, C, h };
  }

  function oklchToRgb(L, C, h) {
    const a = C * Math.cos(h * Math.PI / 180);
    const b = C * Math.sin(h * Math.PI / 180);
    const lp = L + 0.3963377774*a + 0.2158037573*b;
    const mp = L - 0.1055613458*a - 0.0638541728*b;
    const sp = L - 0.0894841775*a - 1.2914855480*b;
    const l = lp*lp*lp, m = mp*mp*mp, s = sp*sp*sp;
    return [
      gamma( 4.0767416621*l - 3.3077115913*m + 0.2309699292*s),
      gamma(-1.2684380046*l + 2.6097574011*m - 0.3413193965*s),
      gamma(-0.0041960863*l - 0.7034186147*m + 1.7076147010*s)
    ];
  }

  function inGamut(rgb) { return rgb.every(c => c >= 0 && c <= 1); }

  function gamutMappedHex(L, C, h) {
    let lo = 0, hi = Math.max(0, C), rgb = oklchToRgb(L, hi, h);
    if (!inGamut(rgb)) {
      for (let i = 0; i < 24; i++) {
        const mid = (lo + hi) / 2;
        const test = oklchToRgb(L, mid, h);
        if (inGamut(test)) { lo = mid; rgb = test; } else hi = mid;
      }
    }
    return '#' + rgb.map(c => Math.round(q(c, 0, 1) * 255).toString(16).padStart(2, '0')).join('');
  }

  function recolorElement(el, attribute, sourceHex, theme, reference) {
    const source = rgbToOklch(parseColor(sourceHex));
    const scale = reference.C > 1e-7 ? theme.C / reference.C : 0;
    const mapped = gamutMappedHex(source.L, source.C * scale, theme.h);
    el.setAttribute(attribute, mapped);
  }

  function setAccent(value) {
    const rgb = parseColor(value);
    if (!rgb) return false;
    const theme = rgbToOklch(rgb);
    const reference = rgbToOklch(parseColor('#00f044'));
    root.querySelectorAll('[data-glow-source]').forEach(el => {
      const props = (el.dataset.colorProperty || '').split(/\s+/).filter(Boolean);
      props.forEach(prop => recolorElement(el, prop, el.dataset.glowSource, theme, reference));
      if (el.dataset.strokeSource) recolorElement(el, 'stroke', el.dataset.strokeSource, theme, reference);
    });
    root.dataset.accent = value;
    return true;
  }

  root.setPompuiAccent = setAccent;
  addEventListener('pompui-accent-change', event => setAccent(event.detail && event.detail.color));

  const requested = new URLSearchParams(location.search).get('accent');
  const cssAccent = getComputedStyle(root).getPropertyValue('--pompui-accent').trim();
  setAccent(requested || cssAccent || root.dataset.accent || '#00f044');

  let lastAccent = root.dataset.accent;
  new MutationObserver(() => {
    const cssValue = getComputedStyle(root).getPropertyValue('--pompui-accent').trim();
    const next = cssValue || root.dataset.accent;
    if (next && next !== lastAccent) {
      lastAccent = next;
      setAccent(next);
    }
  }).observe(root, { attributes: true, attributeFilter: ['data-accent', 'class', 'style'] });
})();
